# =====================================================================
# Check of the WeCoPS R code WITHOUT building or installing the package.
# Open this file in R or RStudio and run it entirely (Source).
# A window opens: select the file DESCRIPTION inside the folder WeCoPS.
# The script prints "OK" or "PROBLEM" for each check, then a summary.
# =====================================================================
cat("Select the file DESCRIPTION of the WeCoPS folder...\n")
pkg <- dirname(file.choose())
for (f in list.files(file.path(pkg, "R"), pattern = "[.]R$", full.names = TRUE)) source(f)
.read_ext <- function(name, header = TRUE) {
  f <- file.path(pkg, "inst", "extdata", name)
  if (header) as.matrix(read.csv(f, check.names = FALSE, row.names = 1))
  else unname(as.matrix(read.csv(f, header = FALSE)))
}
n_ok <- 0; n_pb <- 0
check <- function(label, ok) {
  ok <- isTRUE(ok)
  cat(sprintf("%-8s %s\n", if (ok) "OK" else "PROBLEM", label))
  if (ok) n_ok <<- n_ok + 1 else n_pb <<- n_pb + 1
}
near <- function(a, b, tol) isTRUE(all(abs(a - b) <= tol))
cat("\n--- 1. weights, eigenvalues, motifs, saliences ---\n")

b <- load_simulated(1)$blocks; a <- wecops(b, 5)
check("sim1: weights rv", near(block_weights(b, "rv"), c(1.74192226, 1.5731582, 1.03682773), 1e-6))
check("sim1: weights mfa", near(block_weights(b, "mfa"), c(2.09395304, 1.70731014, 1.03694352), 1e-6))
check("sim1: weights statis", near(block_weights(b, "statis"), c(1.23112117, 1.11198201, 0.03036317), 1e-6))
