cat("\n--- 3. independence from the signs of the principal components ---\n")
b <- load_simulated(4)$blocks; U <- cpca(b, R = 5)$U
check("same common and proper components after changing signs", near(ccp(b, U)$S, ccp(b, sweep(U, 2, c(1, -1, 1, -1, 1), `*`))$S, 1e-8))
cat("\n--- 4. diagnostic sheet ---\n")
r <- compare_weighting(load_butters()$blocks, 4, "nvar", block_names = c("VIS", "NIR", "MIR"))
print(r)
f <- file.path(tempdir(), "fiche_test.png")
ok <- tryCatch({ plot_fiche(r, file = f); file.exists(f) }, error = function(e) { cat(conditionMessage(e), "\n"); FALSE })
check(paste("plot_fiche writes", f), ok)
cat(sprintf("\n===== %d checks OK, %d problems =====\n", n_ok, n_pb))
if (n_pb > 0) cat("Please send the lines marked PROBLEM (or the whole output).\n")
